struct ListsMatrixItemItemCodec
{
    using Value = Mode;

    [[nodiscard]] static WireError encode(const Value& value, cont::BitWriter& w,
                                          [[maybe_unused]] u16 minor) noexcept
    {
        if (!enum_known(value, minor))
        {
            return enum_known(value, kMinor) ? WireError::NotInRevision : WireError::UnknownValue;
        }
        w.put(static_cast<u64>(value), 3U);
        return WireError::Ok;
    }

    [[nodiscard]] static u64 end([[maybe_unused]] const Value& value, [[maybe_unused]] u16 minor,
                                 u64 position) noexcept
    {
        position += 3U;
        return position;
    }

    [[nodiscard]] static WireError decode(cont::BitReader& r, [[maybe_unused]] u16 writer_minor,
                                          Value& value) noexcept
    {
        if (const WireError error = wire_take_uint(r, 3U, value); error != WireError::Ok)
        {
            return error;
        }
        if (writer_minor <= kMinor && !enum_known(value, writer_minor))
        {
            return WireError::UnknownValue;
        }
        return WireError::Ok;
    }

    [[nodiscard]] static bool same(const Value& a, const Value& b) noexcept
    {
        return wire_same(a, b);
    }
};

