struct ListsCodec;

struct Lists
{
    using WireCodec = ListsCodec;

    WireList<ListsSmallItemCodec>  small;
    WireList<ListsExactItemCodec>  exact;
    WireList<NodeCodec>            nodes;
    WireList<ListsMatrixItemCodec> matrix;
    WireList<ListsWordsItemCodec>  words;
};

struct ListsCodec
{
    using Value = Lists;
    static constexpr u16 kSchemaMinor = kMinor;
    static constexpr u32 kMessageId = 3U;
    static constexpr u32 kMinBytes = 9U; // at the first minor revision
    static constexpr u32 kMaxBytes = 299U; // at the current minor revision
    static constexpr bool kLossy = false; // a decoded value may re-encode to other bits

    [[nodiscard]] static WireError encode(const Value& value, cont::BitWriter& w,
                                                 [[maybe_unused]] u16 minor) noexcept
    {
        if (const WireError error = wire_put_list(w, value.small, 0U, 9U, 4U, minor); error != WireError::Ok)
        {
            return error;
        }
        if (const WireError error = wire_put_list(w, value.exact, 2U, 2U, 0U, minor); error != WireError::Ok)
        {
            return error;
        }
        if (const WireError error = wire_put_list(w, value.nodes, 1U, 6U, 3U, minor); error != WireError::Ok)
        {
            return error;
        }
        if (const WireError error = wire_put_list(w, value.matrix, 0U, 3U, 2U, minor);
            error != WireError::Ok)
        {
            return error;
        }
        if (const WireError error = wire_put_list(w, value.words, 0U, 3U, 2U, minor); error != WireError::Ok)
        {
            return error;
        }
        return WireError::Ok;
    }

    [[nodiscard]] static u64 end([[maybe_unused]] const Value& value, [[maybe_unused]] u16 minor,
                                 u64 position) noexcept
    {
        position = wire_list_end(value.small, 4U, minor, position);
        position = wire_list_end(value.exact, 0U, minor, position);
        position = wire_list_end(value.nodes, 3U, minor, position);
        position = wire_list_end(value.matrix, 2U, minor, position);
        position = wire_list_end(value.words, 2U, minor, position);
        return position;
    }

    [[nodiscard]] static WireError decode(cont::BitReader& r, [[maybe_unused]] u16 writer_minor,
                                                 Value& value) noexcept
    {
        value = Value{};
        if (const WireError error = wire_take_list(r, 0U, 9U, 4U, writer_minor, value.small);
            error != WireError::Ok)
        {
            return error;
        }
        if (const WireError error = wire_take_list(r, 2U, 2U, 0U, writer_minor, value.exact);
            error != WireError::Ok)
        {
            return error;
        }
        if (const WireError error = wire_take_list(r, 1U, 6U, 3U, writer_minor, value.nodes);
            error != WireError::Ok)
        {
            return error;
        }
        if (const WireError error = wire_take_list(r, 0U, 3U, 2U, writer_minor, value.matrix);
            error != WireError::Ok)
        {
            return error;
        }
        if (const WireError error = wire_take_list(r, 0U, 3U, 2U, writer_minor, value.words);
            error != WireError::Ok)
        {
            return error;
        }
        return WireError::Ok;
    }

    [[nodiscard]] static bool same(const Value& a, const Value& b) noexcept
    {
        return wire_same_list(a.small, b.small) &&
               wire_same_list(a.exact, b.exact) &&
               wire_same_list(a.nodes, b.nodes) &&
               wire_same_list(a.matrix, b.matrix) &&
               wire_same_list(a.words, b.words);
    }
};

