struct RevisionsCodec;

struct Revisions
{
    using WireCodec = RevisionsCodec;

    u16                               first = 0U;
    Extended                          extended;
    u8                                note = static_cast<u8>(9ULL);
    u16                               count = 0U;
    Mode                              named = Mode::Auto;
    cont::ConstSpan<u8>               tail;
    bool                              has_node = false;
    Node                              node;
    WireList<RevisionsItemsItemCodec> items;
};

struct RevisionsCodec
{
    using Value = Revisions;
    static constexpr u16 kSchemaMinor = kMinor;
    static constexpr u32 kMessageId = 4U;
    static constexpr u32 kMinBytes = 5U; // at the first minor revision
    static constexpr u32 kMaxBytes = 100U; // at the current minor revision
    static constexpr bool kLossy = false; // a decoded value may re-encode to other bits

    [[nodiscard]] static WireError encode(const Value& value, cont::BitWriter& w,
                                                 [[maybe_unused]] u16 minor) noexcept
    {
        if ((static_cast<u64>(value.first) >> 11U) != 0U)
        {
            return WireError::OutOfRange;
        }
        w.put(value.first, 11U);
        if (const WireError error = ExtendedCodec::encode(value.extended, w, minor); error != WireError::Ok)
        {
            return error;
        }
        if (minor >= 1U)
        {
            if ((static_cast<u64>(value.note) >> 5U) != 0U)
            {
                return WireError::OutOfRange;
            }
            w.put(value.note, 5U);
        }
        else if (value.note != static_cast<u8>(9ULL))
        {
            return WireError::NotInRevision;
        }
        if (minor >= 1U)
        {
            if (static_cast<u64>(value.count) > 1000ULL)
            {
                return WireError::OutOfRange;
            }
            wire_put_varuint(w, value.count, 7U);
        }
        else if (value.count != static_cast<u16>(0ULL))
        {
            return WireError::NotInRevision;
        }
        if (minor >= 1U)
        {
            if (!enum_known(value.named, minor))
            {
                return enum_known(value.named, kMinor) ? WireError::NotInRevision : WireError::UnknownValue;
            }
            w.put(static_cast<u64>(value.named), 3U);
        }
        else if (value.named != Mode::Auto)
        {
            return WireError::NotInRevision;
        }
        if (minor >= 2U)
        {
            if (value.tail.size() > 12U)
            {
                return WireError::OutOfRange;
            }
            wire_put_bytes(w, value.tail, 0U, 4U);
        }
        else if (!value.tail.empty())
        {
            return WireError::NotInRevision;
        }
        if (minor >= 2U)
        {
            w.put(value.has_node ? 1U : 0U, 1U);
            if (value.has_node)
            {
                if (const WireError error = NodeCodec::encode(value.node, w, minor); error != WireError::Ok)
                {
                    return error;
                }
            }
        }
        else if (value.has_node)
        {
            return WireError::NotInRevision;
        }
        if (minor >= 2U)
        {
            if (const WireError error = wire_put_list(w, value.items, 0U, 4U, 3U, minor); error != WireError::Ok)
            {
                return error;
            }
        }
        else if (!value.items.empty())
        {
            return WireError::NotInRevision;
        }
        return WireError::Ok;
    }

    [[nodiscard]] static u64 end([[maybe_unused]] const Value& value, [[maybe_unused]] u16 minor,
                                 u64 position) noexcept
    {
        position += 11U;
        position = ExtendedCodec::end(value.extended, minor, position);
        if (minor >= 1U)
        {
            position += 5U;
        }
        if (minor >= 1U)
        {
            position += wire_varuint_bits(value.count, 7U);
        }
        if (minor >= 1U)
        {
            position += 3U;
        }
        if (minor >= 2U)
        {
            position = wire_bytes_end(position, 4U, value.tail.size());
        }
        if (minor >= 2U)
        {
            position += 1U;
            if (value.has_node)
            {
                position = NodeCodec::end(value.node, minor, position);
            }
        }
        if (minor >= 2U)
        {
            position = wire_list_end(value.items, 3U, minor, position);
        }
        return position;
    }

    [[nodiscard]] static WireError decode(cont::BitReader& r, [[maybe_unused]] u16 writer_minor,
                                                 Value& value) noexcept
    {
        value = Value{};
        if (const WireError error = wire_take_uint(r, 11U, value.first); error != WireError::Ok)
        {
            return error;
        }
        if (const WireError error = ExtendedCodec::decode(r, writer_minor, value.extended);
            error != WireError::Ok)
        {
            return error;
        }
        if (writer_minor >= 1U)
        {
            if (const WireError error = wire_take_uint(r, 5U, value.note); error != WireError::Ok)
            {
                return error;
            }
        }
        if (writer_minor >= 1U)
        {
            if (const WireError error = wire_take_varuint_as(r, 7U, 1000ULL, value.count);
                error != WireError::Ok)
            {
                return error;
            }
        }
        if (writer_minor >= 1U)
        {
            if (const WireError error = wire_take_uint(r, 3U, value.named); error != WireError::Ok)
            {
                return error;
            }
            if (writer_minor <= kMinor && !enum_known(value.named, writer_minor))
            {
                return WireError::UnknownValue;
            }
        }
        if (writer_minor >= 2U)
        {
            if (const WireError error = wire_take_bytes(r, 0U, 12U, 4U, value.tail); error != WireError::Ok)
            {
                return error;
            }
        }
        if (writer_minor >= 2U)
        {
            if (const WireError error = wire_take_bool(r, value.has_node); error != WireError::Ok)
            {
                return error;
            }
            if (value.has_node)
            {
                if (const WireError error = NodeCodec::decode(r, writer_minor, value.node); error != WireError::Ok)
                {
                    return error;
                }
            }
        }
        if (writer_minor >= 2U)
        {
            if (const WireError error = wire_take_list(r, 0U, 4U, 3U, writer_minor, value.items);
                error != WireError::Ok)
            {
                return error;
            }
        }
        return WireError::Ok;
    }

    [[nodiscard]] static bool same(const Value& a, const Value& b) noexcept
    {
        return wire_same(a.first, b.first) &&
               ExtendedCodec::same(a.extended, b.extended) &&
               wire_same(a.note, b.note) &&
               wire_same(a.count, b.count) &&
               wire_same(a.named, b.named) &&
               wire_same_bytes(a.tail, b.tail) &&
               a.has_node == b.has_node &&
               (!a.has_node || NodeCodec::same(a.node, b.node)) &&
               wire_same_list(a.items, b.items);
    }
};

