struct LongBodyCodec;

struct LongBody
{
    using WireCodec = LongBodyCodec;

    u8           before = 0U;
    LongExtended body;
    u8           after = 0U;
};

struct LongBodyCodec
{
    using Value = LongBody;
    static constexpr u16 kSchemaMinor = kMinor;
    static constexpr u32 kMessageId = 7U;
    static constexpr u32 kMinBytes = 4U; // at the first minor revision
    static constexpr u32 kMaxBytes = 307U; // at the current minor revision
    static constexpr bool kLossy = false; // a decoded value may re-encode to other bits

    [[nodiscard]] static WireError encode(const Value& value, cont::BitWriter& w,
                                                 [[maybe_unused]] u16 minor) noexcept
    {
        if ((static_cast<u64>(value.before) >> 3U) != 0U)
        {
            return WireError::OutOfRange;
        }
        w.put(value.before, 3U);
        if (const WireError error = LongExtendedCodec::encode(value.body, w, minor); error != WireError::Ok)
        {
            return error;
        }
        if ((static_cast<u64>(value.after) >> 5U) != 0U)
        {
            return WireError::OutOfRange;
        }
        w.put(value.after, 5U);
        return WireError::Ok;
    }

    [[nodiscard]] static u64 end([[maybe_unused]] const Value& value, [[maybe_unused]] u16 minor,
                                 u64 position) noexcept
    {
        position += 3U;
        position = LongExtendedCodec::end(value.body, minor, position);
        position += 5U;
        return position;
    }

    [[nodiscard]] static WireError decode(cont::BitReader& r, [[maybe_unused]] u16 writer_minor,
                                                 Value& value) noexcept
    {
        value = Value{};
        if (const WireError error = wire_take_uint(r, 3U, value.before); error != WireError::Ok)
        {
            return error;
        }
        if (const WireError error = LongExtendedCodec::decode(r, writer_minor, value.body);
            error != WireError::Ok)
        {
            return error;
        }
        if (const WireError error = wire_take_uint(r, 5U, value.after); error != WireError::Ok)
        {
            return error;
        }
        return WireError::Ok;
    }

    [[nodiscard]] static bool same(const Value& a, const Value& b) noexcept
    {
        return wire_same(a.before, b.before) &&
               LongExtendedCodec::same(a.body, b.body) &&
               wire_same(a.after, b.after);
    }
};

inline constexpr hesap::net::BoundedFloat kQuantizedHeightFormat =
    wire_bounded_format(-100.0F, 100.0F, 65535U);
static_assert(kQuantizedHeightFormat.bits == 16U);
inline constexpr hesap::net::BoundedFloat kQuantizedFineFormat =
    wire_bounded_format(0.0F, 1.0F, 1000U);
static_assert(kQuantizedFineFormat.bits == 10U);
inline constexpr hesap::net::SmallestThree kQuantizedTurnFormat = wire_smallest_three_format(12U);
inline constexpr hesap::net::SmallestThree kQuantizedPathItemFormat = wire_smallest_three_format(9U);

struct QuantizedPathItemCodec
{
    using Value = WireQuaternion;

    [[nodiscard]] static WireError encode(const Value& value, cont::BitWriter& w,
                                          [[maybe_unused]] u16 minor) noexcept
    {
        if (!wire_quaternion_finite(value))
        {
            return WireError::NonFinite;
        }
        wire_put_quaternion(w, kQuantizedPathItemFormat, value);
        return WireError::Ok;
    }

    [[nodiscard]] static u64 end([[maybe_unused]] const Value& value, [[maybe_unused]] u16 minor,
                                 u64 position) noexcept
    {
        position += 29U;
        return position;
    }

    [[nodiscard]] static WireError decode(cont::BitReader& r, [[maybe_unused]] u16 writer_minor,
                                          Value& value) noexcept
    {
        if (const WireError error = wire_take_quaternion(r, kQuantizedPathItemFormat, value);
            error != WireError::Ok)
        {
            return error;
        }
        return WireError::Ok;
    }

    [[nodiscard]] static bool same(const Value& a, const Value& b) noexcept
    {
        return wire_same(a, b);
    }
};

struct QuantizedCodec;

struct Quantized
{
    using WireCodec = QuantizedCodec;

    f32                              height = 0.0F;
    f32                              fine = 0.0F;
    WireQuaternion                   turn;
    WireList<QuantizedPathItemCodec> path;
};

struct QuantizedCodec
{
    using Value = Quantized;
    static constexpr u16 kSchemaMinor = kMinor;
    static constexpr u32 kMessageId = 6U;
    static constexpr u32 kMinBytes = 9U; // at the first minor revision
    static constexpr u32 kMaxBytes = 23U; // at the current minor revision
    static constexpr bool kLossy = true; // a decoded value may re-encode to other bits

    [[nodiscard]] static WireError encode(const Value& value, cont::BitWriter& w,
                                                 [[maybe_unused]] u16 minor) noexcept
    {
        if (!wire_finite(value.height))
        {
            return WireError::NonFinite;
        }
        w.put(hesap::net::bounded_encode(kQuantizedHeightFormat, value.height), 16U);
        if (!wire_finite(value.fine))
        {
            return WireError::NonFinite;
        }
        w.put(hesap::net::bounded_encode(kQuantizedFineFormat, value.fine), 10U);
        if (!wire_quaternion_finite(value.turn))
        {
            return WireError::NonFinite;
        }
        wire_put_quaternion(w, kQuantizedTurnFormat, value.turn);
        if (const WireError error = wire_put_list(w, value.path, 0U, 4U, 3U, minor); error != WireError::Ok)
        {
            return error;
        }
        return WireError::Ok;
    }

    [[nodiscard]] static u64 end([[maybe_unused]] const Value& value, [[maybe_unused]] u16 minor,
                                 u64 position) noexcept
    {
        position += 16U;
        position += 10U;
        position += 38U;
        position = wire_list_end(value.path, 3U, minor, position);
        return position;
    }

    [[nodiscard]] static WireError decode(cont::BitReader& r, [[maybe_unused]] u16 writer_minor,
                                                 Value& value) noexcept
    {
        value = Value{};
        if (const WireError error = wire_take_bounded(r, kQuantizedHeightFormat, value.height);
            error != WireError::Ok)
        {
            return error;
        }
        if (const WireError error = wire_take_bounded(r, kQuantizedFineFormat, value.fine);
            error != WireError::Ok)
        {
            return error;
        }
        if (const WireError error = wire_take_quaternion(r, kQuantizedTurnFormat, value.turn);
            error != WireError::Ok)
        {
            return error;
        }
        if (const WireError error = wire_take_list(r, 0U, 4U, 3U, writer_minor, value.path);
            error != WireError::Ok)
        {
            return error;
        }
        return WireError::Ok;
    }

    [[nodiscard]] static bool same(const Value& a, const Value& b) noexcept
    {
        return wire_same(a.height, b.height) &&
               wire_same(a.fine, b.fine) &&
               wire_same(a.turn, b.turn) &&
               wire_same_list(a.path, b.path);
    }
};

